/**
 * Typed loader over the build-time ville dataset (lib/tribunaux/villes.json,
 * generated by scripts/seo/build-villes.ts from Supabase auction data).
 *
 * Consumed by the programmatic-SEO route /encheres/[ville] and the landing's
 * SEO hub. Static JSON → zero runtime DB cost; regenerate when data shifts.
 */
import villesData from "./villes.json";
import type { PropertyTypeBucket } from "@/lib/analytics/normalize-property-type";

export interface VilleStats {
  total: number;
  sold: number;
  upcoming: number;
  medianMiseAPrix: number | null;
  medianAdjudication: number | null;
  /** Median (1 − adjudication/DVF) over sold rows with DVF. 0.32 ⇒ −32 % vs marché. */
  medianDecoteVsDvf: number | null;
}

export interface Ville {
  slug: string;
  ville: string;
  tribunal: string;
  department: string | null;
  stats: VilleStats;
  topPropertyTypes: { type: PropertyTypeBucket; count: number }[];
  lastAuctionDate: string | null;
}

const VILLES = villesData as Ville[];
const BY_SLUG = new Map(VILLES.map((v) => [v.slug, v]));

/** All villes, ordered by auction volume (densest first). */
export function getAllVilles(): Ville[] {
  return VILLES;
}

export function getVilleBySlug(slug: string): Ville | undefined {
  return BY_SLUG.get(slug);
}

/** Slugs for generateStaticParams. */
export function villeSlugs(): string[] {
  return VILLES.map((v) => v.slug);
}

/** Densest N villes for the landing-page SEO hub. */
export function getFeaturedVilles(n = 12): Ville[] {
  return VILLES.slice(0, n);
}
